 return [nms[0],nms[1]-base_v*nms[0],nms[2]-base_v*nms[1],ww*(xi*xi-a*xi-b)**2/den]
print('start',flush=True);t0=time.time()
a=mp([Jet(m),e,p*e**2,q*e**4],u,v);print('first',time.time()-t0,flush=True)
